mapper.select:
		/** TermsSearchMapper.countByTitle */
		SELECT
            COUNT(TERMS_ID)
        FROM
            TERMS
        WHERE
            TITLE = #{title}


            AND TERMS_ID <> #{termsId}

		/** TermsSearchMapper.countByOrderNo */
		SELECT
            COUNT(TERMS_ID)
        FROM
            TERMS
        WHERE
            USE_YN = 'Y'
            AND ORDER_NO = #{orderNo}


            AND TERMS_ID <> #{termsId}

/** TermsSearchMapper.list */ SELECT TERMS_ID, TITLE, CONTENTS, CONTENT_TYPE, ORDER_NO, USE_YN, REQUIRE_YN, CREATE_ID, CREATE_DATE, UPDATE_ID, UPDATE_DATE FROM TERMS WHERE 1=1
AND TITLE LIKE CONCAT('%', #{title}, '%')
AND CONTENT_TYPE = #{contentType}
AND USE_YN = #{useYn}
AND REQUIRE_YN = #{requireYn}
ORDER BY CREATE_DATE DESC
